func VerifyHardcodedSectionColorsResolved(ctx context.Context, db *sql.DB, spec map[string]interface{}, logger *zap.Logger) (VerifyResult, error) {
    componentID, _ := spec["component_id"].(string)
    if componentID == "" {
        return VerifyResult{}, fmt.Errorf("hardcoded_section_colors spec has no component_id")
    }
    if _, err := uuid.Parse(componentID); err != nil {
        return VerifyResult{}, fmt.Errorf("hardcoded_section_colors spec component_id %q: %w", componentID, err)
    }
    var html sql.NullString
    err := db.QueryRowContext(ctx, `SELECT rendered_html FROM page_components WHERE id = $1`, componentID).Scan(&html)
    if err == sql.ErrNoRows {
        // Same corrected policy as edit 1 - absent is UNKNOWN, not resolved.
        return VerifyResult{}, fmt.Errorf("cannot verify: component %s no longer exists", componentID)
    }
    if err != nil {
        return VerifyResult{}, err
    }
    return hardcodedColorVerdict(html.String), nil
}

