func VerifyPhantomInternalLinkResolved(ctx context.Context, db *sql.DB, spec map[string]interface{}, logger *zap.Logger) (VerifyResult, error) {
    // Re-run the SAME resolution predicate the check uses to decide a link is
    // phantom, against the link recorded in spec.
    //   target now resolves            -> VerifyResult{Resolved: true}
    //   target still does not resolve  -> VerifyResult{Resolved: false}
    //   the link/section is GONE       -> error ("cannot verify: link absent")
    //     NOT Resolved:true - a rebuild that dropped the section is
    //     indistinguishable from a fix at this layer (bug_historian, council
    //     66dbd0dd). Fails open via the gate, recorded in result._verification.
    // Extract that predicate from the detection path into a shared func rather
    // than restating the rule - a second copy is the drift this change exists
    // to prevent.
}

