// VerifierCoverage reports which registered item_types have a completion
// verifier and which complete on the handler's self-report alone.
// Exported so tests and reports can assert on the gap rather than relying on
// anyone reading a comment (council 66dbd0dd, bug_historian).
func VerifierCoverage() (covered []string, uncovered []string) {
    for itemType := range registeredChecks() {   // the existing check registry
        if _, ok := verifiers[itemType]; ok {
            covered = append(covered, itemType)
        } else {
            uncovered = append(uncovered, itemType)
        }
    }
    sort.Strings(covered); sort.Strings(uncovered)
    return
}

// itemTypesKnowinglyUnverified lists item_types that complete on the handler's
// self-report. Adding a check without a verifier fails this test - add the
// verifier, or add the item_type here with a one-line reason.
var itemTypesKnowinglyUnverified = map[string]string{
    "page_rerender": "no cheap deterministic predicate; rendered output is the artefact",
    // ... the remaining current gaps, each with a reason
}

func TestVerifierCoverage_KnownGapsOnly(t *testing.T) {
    _, uncovered := VerifierCoverage()
    for _, it := range uncovered {
        if _, allowed := itemTypesKnowinglyUnverified[it]; !allowed {
            t.Errorf("item_type %q has a discovery check but no verifier and is not on the known-gap list: register a verifier, or add it with a reason", it)
        }
    }
}
